7	 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
8	 * See LICENSE in the root of the software repository for the full text of the License.
9	 */
10	
11	#include <errno.h>
12	#include <sys/mman.h>
13	#include <sys/syscall.h>
14	#include <linux/mempolicy.h>
15	#include "user_log.h"
16	#include "securec.h"
17	#include "ascend_hal.h"
18	#include "ascend_hal_define.h"
19	#include "hns_roce_hal.h"
20	
21	static inline unsigned long long align(unsigned long long val, unsigned int align)
22	{
23	    return (val + align - 1) & ~((unsigned long long)align - 1);
24	}
25	
26	int hns_roce_hal_alloc_buf(void **buf, unsigned int *length, unsigned int size, unsigned int page_size,
27	    unsigned int dev_id)
28	{
29	#define NODE_MASK_LIST_NUM 2
30	#define MAX_NODE_BIT_NUM 128
31	#define NODE_LONG_BIT_NUM 64
32	#define PAGE_ALIGN_2MB (2 * 1024 * 1024)
33	    unsigned long long node_mask[NODE_MASK_LIST_NUM] = {0};
34	    int flags = MAP_PRIVATE | MAP_ANONYMOUS;
35	    unsigned long long node_index = 0;
36	    unsigned long long node_cnt, i;
37	    struct MemInfo info = {0};
38	    unsigned int max_node = 0;
39	    int ret;
40	
41	    if (size == 0 || page_size == 0) {
42	        roce_err("hns_roce_hal_alloc_buf size %u or page_size %u is zero!", size, page_size);
43	        return -EINVAL;
44	    }
45	
46	    *length = align(size, page_size);
47	
48	    ret = (int)halMemGetInfo(dev_id, MEM_INFO_TYPE_BAR_NUMA_INFO, &info);
49	    if (ret) {
50	        roce_err("hns_roce_hal_alloc_buf: halMemGetInfo failed, ret [%d]", ret);
51	        return ret;
52	    }
53	
54	    node_cnt = (unsigned long long)info.numa_info.node_cnt;
55	    if (node_cnt > sizeof(info.numa_info.node_id) / sizeof(int)) {
56	        roce_err("hns_roce_hal_alloc_buf: halMemGetInfom node_cnt 0x%llx", node_cnt);
57	        return -EINVAL;
58	    }
59	
60	    for (i = 0; i < node_cnt; i++) {
61	        node_index = (unsigned long long)info.numa_info.node_id[i];
62	        if (node_index >= MAX_NODE_BIT_NUM) {
63	            roce_err("hns_roce_hal_alloc_buf: halMemGetInfom node_index 0x%llx > %d, failed!", node_index,
64	                     MAX_NODE_BIT_NUM);
65	            return -EINVAL;
66	        }
67	
68	        max_node = (node_index > max_node) ? node_index : max_node;
69	
70	        if (node_index >= NODE_LONG_BIT_NUM) {
71	            node_index -= NODE_LONG_BIT_NUM;
72	            node_mask[1] |= ((unsigned long long)1 << node_index);
73	        } else {
74	            node_mask[0] |= ((unsigned long long)1 << node_index);
75	        }
76	    }
77	
78	    // plus 2 to avoid kernel get_nodes maxnode param high-order truncation bug
79	    max_node += 2;
80	
81	    if (page_size == PAGE_ALIGN_2MB) {
82	        flags |= MAP_HUGETLB;
83	    }
84	    *buf = mmap(NULL, *length, PROT_READ | PROT_WRITE, flags, -1, 0);
85	    if (*buf == MAP_FAILED) {
86	        roce_err("hns_roce_hal_alloc_buf mmap failed. start addr 0x%llx length 0x%x, err_code %d",
87	                 (unsigned long long)*buf, *length, errno);
88	        return -ENOMEM;
89	    }
90	
91	    ret = syscall(__NR_mbind, *buf, *length, MPOL_BIND, node_mask, max_node, MPOL_MF_MOVE);
92	    if (ret != 0) {
93	        roce_err("hns_roce_hal_alloc_buf mbind failed. start addr 0x%llx length 0x%x, ret = %d\n",
94	                 (unsigned long long)*buf, *length, ret);
95	        goto err_unmamp;
96	    }
97	
98	    ret = memset_s(*buf, *length, 0, *length);
99	    if (ret != 0) {
100	        roce_err("hns_roce_hal_alloc_buf memset_s failed. start addr 0x%llx length 0x%x, ret = %d\n",
101	                 (unsigned long long)*buf, *length, ret);
102	        goto err_unmamp;
103	    }
104	
105	    return 0;
106	
107	err_unmamp:
108	    munmap(*buf, *length);
109	    *buf = NULL;
110	
111	    return -ENOMEM;
112	}
113	
114	int hns_roce_hal_get_dev_id(unsigned int chip_id, unsigned int die_id, unsigned int *dev_id)
115	{
116	    unsigned int *device_list;
117	    unsigned int dev_num = 0;
118	    long int chip_id_val = 0;
119	    long int die_id_val = 0;
120	    unsigned int i;
121	    int ret;
122	
123	    ret = drvGetDevNum(&dev_num);
124	    if (ret) {
125	        roce_err("hns_roce_hal_get_dev_id failed!, ret is %d", ret);
126	        return -EINVAL;
127	    }
128	
129	    if (dev_num == 0) {
130	        roce_err("hns_roce_hal_get_dev_id dev_num is 0, failed!");
131	        return -EINVAL;
132	    }
133	
134	    device_list = (unsigned int *)calloc(dev_num, sizeof(unsigned int));
135	    if (device_list == NULL) {
136	        roce_err("hns_roce_hal_get_dev_id failed, calloc device list failed");
137	        return -ENOMEM;
138	    }
139	
140	    ret = drvGetDeviceLocalIDs(device_list, dev_num);
141	    if (ret) {
142	        roce_err("hns_roce_hal_get_dev_id failed, drvGetDeviceLocalIDs failed, ret is %d", ret);
143	        goto out;
144	    }
145	
146	    for (i = 0; i < dev_num; i++) {
147	        ret = halGetDeviceInfo(device_list[i], MODULE_TYPE_SYSTEM, INFO_TYPE_PHY_CHIP_ID, &chip_id_val);
148	        if (ret) {
149	            roce_err("hns_roce_hal_get_dev_id get chip_id failed, halGetDeviceInfo failed, ret is %d", ret);
150	            goto out;
151	        }
152	
153	        ret = halGetDeviceInfo(device_list[i], MODULE_TYPE_SYSTEM, INFO_TYPE_PHY_DIE_ID, &die_id_val);
