98	STATIC int bitmap_set(unsigned int *bitmap_list, unsigned int list_size, unsigned int index)
99	{
100	    unsigned int word_index = index / BITMAP_WORD_LEN;
101	    unsigned int bit_index = index % BITMAP_WORD_LEN;
102	
103	    if (word_index >= list_size) {
104	        roce_err("set bitmap failed, word_index[%u] >= list_size[%u]", word_index, list_size);
105	        return -EINVAL;
106	    }
107	
108	    if (((bitmap_list[word_index] >> bit_index) & 0x1) != 0) {
109	        roce_err("set bitmap failed, word_index[%u] bit_index[%u] already allocated", word_index, bit_index);
110	        return -EIO;
111	    }
112	
113	    bitmap_list[word_index] = bitmap_list[word_index] | (0x1 << bit_index);
114	    return 0;
115	}
