117	static inline void bitmap_free(unsigned int *bitmap_list, unsigned int list_size, unsigned int index)
118	{
119	    unsigned int word_index = index / BITMAP_WORD_LEN;
120	    unsigned int bit_index = index % BITMAP_WORD_LEN;
121	
122	    if (word_index >= list_size) {
123	        roce_err("free bitmap failed, word_index[%u] >= list_size[%u]", word_index, list_size);
124	        return;
125	    }
126	
127	    bitmap_list[word_index] = bitmap_list[word_index] & (~(1 << bit_index));
128	}
