190	
191	    ctx = to_hr_lite_ctx(lite_ctx);
192	    if (ctx->page_size == PAGE_ALIGN_4KB) {
193	        roce_err("deinit param err, ctx->page_size[%u] invalid", ctx->page_size);
194	        return -EINVAL;
195	    }
196	
197	    if (mem_idx >= BITMAP_WORD_SIZE) {
198	        roce_err("deinit param err, mem_idx[%u] >= %u", mem_idx, BITMAP_WORD_SIZE);
199	        return -EINVAL;
200	    }
201	
202	    mem_pool = ctx->mem_pool_list[mem_idx];
203	    if (mem_pool == NULL || mem_pool->used_size > 0) {
204	        roce_err("deinit param err, mem_idx[%u] mem_pool[%pK] is NULL or used_size > 0", mem_idx, mem_pool);
205	        return -EINVAL;
206	    }
207	
208	    ret = hns_roce_lite_unmmap_host_va(mem_pool->host_buf.dva, ctx);
209	    if (ret != 0) {
210	        return ret;
211	    }
212	
213	    free(mem_pool);
214	    mem_pool = NULL;
215	    ctx->mem_pool_list[mem_idx] = NULL;
216	    bitmap_free(ctx->mem_bitmap_list, BITMAP_WORD_NUM, mem_idx);
217	
218	    return 0;
219	}
