371	STATIC int hns_roce_lite_create_qp_init(struct hns_roce_lite_context *context, struct hns_roce_lite_qp *qp,
372	    struct rdma_lite_qp_attr *attr)
373	{
374	    int ret;
375	
376	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(context);
377	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(qp);
378	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(attr);
379	
380	    hns_roce_set_lite_qp_attr(qp, attr);
381	    hns_roce_init_lite_qp_indices(qp);
382	
383	    ret = hns_roce_lite_alloc_qp_wrid_init(qp);
384	    if (ret != 0) {
385	        roce_err("%s hns_roce_lite_alloc_qp_wrid_init failed, ret %d", __func__, ret);
386	        return ret;
387	    }
388	
389	    qp->buf.mem_idx = attr->mem_idx;
390	    ret = hns_roce_lite_mmap_hva(&attr->device_qp_attr.qp_buf, &qp->buf, context);
391	    if (ret != 0) {
392	        roce_err("%s hns_roce_lite_mmap_hva qp->buf.hva failed", __func__);
393	        goto alloc_wr_id_err;
394	    }
395	
396	    qp->sdb_buf.mem_idx = attr->mem_idx;
397	    ret = hns_roce_lite_mmap_hdb(&attr->device_qp_attr.sq.db_buf, &qp->sdb_buf, context);
398	    if (ret != 0) {
399	        roce_err("%s hns_roce_lite_mmap_hdb qp->sdb_buf.hva failed", __func__);
400	        goto mmap_sdb_buf_err;
401	    }
402	
403	    qp->rdb_buf.mem_idx = attr->mem_idx;
404	    ret = hns_roce_lite_mmap_hdb(&attr->device_qp_attr.rq.db_buf, &qp->rdb_buf, context);
405	    if (ret != 0) {
406	        roce_err("%s hns_roce_lite_mmap_hdb qp->rdb_buf.hva failed", __func__);
407	        goto mmap_rdb_buf_err;
408	    }
409	
410	    ret = hns_roce_lite_qp_lock_init(qp);
411	    if (ret) {
412	        roce_err("lite_qp lock init failed!, ret:%d", ret);
413	        goto init_qp_lock_err;
414	    }
415	
416	    qp->lite_qp.qp_num = attr->device_qp_attr.qpn;
417	    (void)pthread_mutex_lock(&context->qp_table_mutex);
418	    ret = hns_roce_store_lite_qp(context, qp->lite_qp.qp_num, qp);
419	    if (ret) {
420	        roce_err("hns_roce_store_lite_qp failed!, ret [%d], expect 0", ret);
421	        goto store_lite_qp_err;
422	    }
423	    (void)pthread_mutex_unlock(&context->qp_table_mutex);
424	
425	    return 0;
426	
427	store_lite_qp_err:
428	    (void)pthread_mutex_unlock(&context->qp_table_mutex);
429	    hns_roce_lite_qp_lock_uninit(qp);
430	
431	init_qp_lock_err:
432	    ret = hns_roce_lite_unmmap_hdb(&qp->rdb_buf, context);
433	    if (ret) {
434	        roce_err("hns_roce_lite_unmmap_hdb failed, ret = %d", ret);
435	    }
436	    qp->rdb_buf.hva = NULL;
437	
438	mmap_rdb_buf_err:
439	    ret = hns_roce_lite_unmmap_hdb(&qp->sdb_buf, context);
440	    if (ret) {
441	        roce_err("hns_roce_lite_unmmap_hdb failed, ret = %d", ret);
442	    }
443	    qp->sdb_buf.hva = NULL;
444	
445	mmap_sdb_buf_err:
446	    ret = hns_roce_lite_unmmap_hva(&qp->buf, context);
447	    if (ret) {
448	        roce_err("hns_roce_lite_unmmap_hva failed, ret = %d", ret);
449	    }
450	    qp->buf.hva = NULL;
451	
452	alloc_wr_id_err:
453	    free(qp->rq.wrid);
454	    qp->rq.wrid = NULL;
455	    free(qp->sq.wrid);
456	    qp->sq.wrid = NULL;
457	
458	    return -ENOMEM;
459	}
