558	STATIC struct hns_roce_lite_qp *hns_roce_lite_find_qp(struct hns_roce_lite_context *ctx, u32 qpn)
559	{
560	    u32 tind = (qpn & (ctx->num_qps - 1)) >> (u32)ctx->qp_table_shift;
561	
562	    if (tind < HNS_ROCE_LITE_QP_TABLE_SIZE) {
563	        if (ctx->qp_table[tind].refcnt) {
564	            return ctx->qp_table[tind].table[qpn & (u32)(ctx->qp_table_mask)];
565	        }
566	    }
567	
568	    return NULL;
569	}
