571	STATIC void hns_roce_lite_poll_one_set_wc(struct rdma_lite_wc *lite_wc, u32 qpn, struct hns_roce_lite_qp **cur_qp,
572	    int is_send, struct hns_roce_lite_cqe *cqe)
573	{
574	    struct hns_roce_lite_wq *lite_wq = NULL;
575	    u16 wqe_ctr;
576	
577	    lite_wc->qp_num = qpn & 0xffffff;
578	
579	    if (is_send) {
580	        lite_wq = &(*cur_qp)->sq;
581	        /*
582	         * if sq_signal_bits is 1, the tail pointer first update to
583	         * the wqe corresponding the current cqe
584	         */
585	        if ((*cur_qp)->sq_signal_bits) {
586	            wqe_ctr = (u16)(roce_get_field(cqe->byte_4, CQE_BYTE_4_WQE_IDX_M, CQE_BYTE_4_WQE_IDX_S));
587	            /*
588	             * lite_wq->tail will plus a positive number every time,
589	             * when lite_wq->tail exceeds 32b, it is 0 and acc
590	             */
591	            lite_wq->tail += (u32)(wqe_ctr - (u16) lite_wq->tail) & (lite_wq->wqe_cnt - 1);
592	        }
593	        /* write the wr_id of lite_wq into the lite_wc */
594	        lite_wc->wr_id = lite_wq->wrid[lite_wq->tail & (lite_wq->wqe_cnt - 1)];
595	        ++lite_wq->tail;
596	    } else {
597	        lite_wq = &(*cur_qp)->rq;
598	        lite_wc->wr_id = lite_wq->wrid[lite_wq->tail & (lite_wq->wqe_cnt - 1)];
599	        ++lite_wq->tail;
600	    }
601	}
