603	static void hns_roce_lite_handle_error_cqe(struct hns_roce_lite_cqe *cqe, struct rdma_lite_wc *lite_wc)
604	{
605	    struct cqe_wc_status lite_cqe_wc_array[] = {
606	        { HNS_ROCE_V2_CQE_LOCAL_LENGTH_ERR, RDMA_LITE_WC_LOC_LEN_ERR },
607	        { HNS_ROCE_V2_CQE_LOCAL_QP_OP_ERR, RDMA_LITE_WC_LOC_QP_OP_ERR },
608	        { HNS_ROCE_V2_CQE_LOCAL_PROT_ERR, RDMA_LITE_WC_LOC_PROT_ERR },
609	        { HNS_ROCE_V2_CQE_WR_FLUSH_ERR, RDMA_LITE_WC_WR_FLUSH_ERR },
610	        { HNS_ROCE_V2_CQE_MEM_MANAGERENT_OP_ERR, RDMA_LITE_WC_MW_BIND_ERR },
611	        { HNS_ROCE_V2_CQE_BAD_RESP_ERR, RDMA_LITE_WC_BAD_RESP_ERR },
612	        { HNS_ROCE_V2_CQE_LOCAL_ACCESS_ERR, RDMA_LITE_WC_LOC_ACCESS_ERR },
613	        { HNS_ROCE_V2_CQE_REMOTE_INVAL_REQ_ERR, RDMA_LITE_WC_REM_INV_REQ_ERR },
614	        { HNS_ROCE_V2_CQE_REMOTE_ACCESS_ERR, RDMA_LITE_WC_REM_ACCESS_ERR },
615	        { HNS_ROCE_V2_CQE_REMOTE_OP_ERR, RDMA_LITE_WC_REM_OP_ERR },
616	        { HNS_ROCE_V2_CQE_TRANSPORT_RETRY_EXC_ERR, RDMA_LITE_WC_RETRY_EXC_ERR },
617	        { HNS_ROCE_V2_CQE_RNR_RETRY_EXC_ERR, RDMA_LITE_WC_RNR_RETRY_EXC_ERR },
618	        { HNS_ROCE_V2_CQE_REMOTE_ABORTED_ERR, RDMA_LITE_WC_REM_ABORT_ERR },
619	    };
620	    u32 status = roce_get_field(cqe->byte_4, CQE_BYTE_4_STATUS_M, CQE_BYTE_4_STATUS_S);
621	    int array_num = sizeof(lite_cqe_wc_array) / sizeof(struct cqe_wc_status);
622	    u32 cqe_status = status & HNS_ROCE_LITE_CQE_STATUS_MASK;
623	    int i;
624	
625	    for (i = 0; i < array_num; i++) {
626	        if (cqe_status == lite_cqe_wc_array[i].cqe_status) {
627	            lite_wc->status = lite_cqe_wc_array[i].wc_status;
628	            break;
629	        }
630	    }
631	
632	    if (i == array_num) {
633	        lite_wc->status = RDMA_LITE_WC_GENERAL_ERR;
634	    }
635	
636	    if (lite_wc->status != RDMA_LITE_WC_WR_FLUSH_ERR) {
637	        roce_err("error cqe status: 0x%x", cqe_status);
638	    }
639	}
