641	STATIC void hns_roce_lite_mark_recv_opcode(struct hns_roce_lite_cqe *cqe, struct rdma_lite_wc *lite_wc,
642	    struct rdma_lite_wc_ext *ext)
643	{
644	    u32 opcode;
645	
646	    lite_wc->byte_len = le32toh(cqe->byte_cnt);
647	    opcode  = roce_get_field(cqe->byte_4, CQE_BYTE_4_OPCODE_M, CQE_BYTE_4_OPCODE_S) & HNS_ROCE_LITE_CQE_OPCODE_MASK;
648	
649	    switch (opcode) {
650	        case HNS_ROCE_RECV_OP_RDMA_WRITE_IMM:
651	            lite_wc->opcode = RDMA_LITE_WC_RECV_RDMA_WITH_IMM;
652	            lite_wc->wc_flags = RDMA_LITE_WC_WITH_IMM;
653	            ext->imm_data = le32toh(cqe->immtdata);
654	            break;
655	        case HNS_ROCE_RECV_OP_SEND:
656	            lite_wc->opcode = RDMA_LITE_WC_RECV;
657	            lite_wc->wc_flags = 0;
658	            break;
659	        case HNS_ROCE_RECV_OP_SEND_WITH_IMM:
660	            lite_wc->opcode = RDMA_LITE_WC_RECV;
661	            lite_wc->wc_flags = RDMA_LITE_WC_WITH_IMM;
662	            ext->imm_data = le32toh(cqe->immtdata);
663	            break;
664	        case HNS_ROCE_RECV_OP_SEND_WITH_INV:
665	            lite_wc->opcode = RDMA_LITE_WC_RECV;
666	            lite_wc->wc_flags = RDMA_LITE_WC_WITH_INV;
667	            ext->invalidated_rkey = le32toh(cqe->rkey);
668	            break;
669	        default:
670	            lite_wc->status = RDMA_LITE_WC_GENERAL_ERR;
671	            roce_err("unknown opcode: 0x%08x", opcode);
672	            break;
673	    }
674	}
