676	STATIC void hns_roce_lite_mark_send_opcode(int is_send, struct hns_roce_lite_cqe *cqe, struct rdma_lite_wc *lite_wc)
677	{
678	    u32 opcode;
679	
680	    if (is_send) {
681	    /* Get opcode and flag before update the tail point for send */
682	        opcode  = roce_get_field(cqe->byte_4, CQE_BYTE_4_OPCODE_M, CQE_BYTE_4_OPCODE_S) & HNS_ROCE_LITE_CQE_OPCODE_MASK;
683	        lite_wc->wc_flags = 0;
684	        switch (opcode) {
685	            case HNS_ROCE_SQ_OP_SEND:
686	                lite_wc->opcode = RDMA_LITE_WC_SEND;
687	                break;
688	            case HNS_ROCE_SQ_OP_SEND_WITH_IMM:
689	                lite_wc->opcode = RDMA_LITE_WC_SEND;
690	                lite_wc->wc_flags = RDMA_LITE_WC_WITH_IMM;
691	                break;
692	            case HNS_ROCE_SQ_OP_SEND_WITH_INV:
693	                lite_wc->opcode = RDMA_LITE_WC_SEND;
694	                break;
695	            case HNS_ROCE_SQ_OP_RDMA_READ:
696	                lite_wc->opcode = RDMA_LITE_WC_RDMA_READ;
697	                lite_wc->byte_len = le32toh(cqe->byte_cnt);
698	                break;
699	            case HNS_ROCE_SQ_OP_RDMA_WRITE:
700	                lite_wc->opcode = RDMA_LITE_WC_RDMA_WRITE;
701	                break;
702	            case HNS_ROCE_SQ_OP_RDMA_WRITE_WITH_IMM:
703	                lite_wc->opcode = RDMA_LITE_WC_RDMA_WRITE;
704	                lite_wc->wc_flags = RDMA_LITE_WC_WITH_IMM;
705	                break;
706	            case HNS_ROCE_SQ_OP_LOCAL_INV:
707	                lite_wc->opcode = RDMA_LITE_WC_LOCAL_INV;
708	                lite_wc->wc_flags = RDMA_LITE_WC_WITH_INV;
709	                break;
710	            case HNS_ROCE_SQ_OP_ATOMIC_COMP_AND_SWAP:
711	                lite_wc->opcode = RDMA_LITE_WC_COMP_SWAP;
712	                lite_wc->byte_len  = BYTE_LEN;
713	                break;
714	            case HNS_ROCE_SQ_OP_ATOMIC_MASK_COMP_AND_SWAP:
715	                lite_wc->opcode = (enum rdma_lite_wc_opcode)HNS_ROCE_WC_MASK_COMP_SWAP;
716	                lite_wc->byte_len  = BYTE_LEN;
717	                break;
718	            case HNS_ROCE_SQ_OP_ATOMIC_FETCH_AND_ADD:
719	                lite_wc->opcode = RDMA_LITE_WC_FETCH_ADD;
720	                lite_wc->byte_len  = BYTE_LEN;
721	                break;
722	            case HNS_ROCE_SQ_OP_ATOMIC_MASK_FETCH_AND_ADD:
723	                lite_wc->opcode = (enum rdma_lite_wc_opcode)HNS_ROCE_WC_MASK_FETCH_ADD;
724	                lite_wc->byte_len  = BYTE_LEN;
725	                break;
726	            case HNS_ROCE_SQ_OP_BIND_MW:
727	                lite_wc->opcode = RDMA_LITE_WC_BIND_MW;
728	                break;
729	            case HNS_ROCE_SQ_OP_NOP:
730	                lite_wc->opcode = (enum rdma_lite_wc_opcode)HNS_ROCE_WC_NOP;
731	                break;
732	            case HNS_ROCE_SQ_OP_REDUCE_WRITE:
733	                lite_wc->opcode = (enum rdma_lite_wc_opcode)HNS_ROCE_WC_REDUCE_WRITE;
734	                break;
735	            case HNS_ROCE_SQ_OP_REDUCE_WRITE_NOTIFY:
736	                lite_wc->opcode = (enum rdma_lite_wc_opcode)HNS_ROCE_WC_REDUCE_WRITE_NOTIFY;
737	                break;
738	            case HNS_ROCE_SQ_OP_WRITE_NOTIFY:
739	                lite_wc->opcode = (enum rdma_lite_wc_opcode)HNS_ROCE_WC_WRITE_NOTIFY;
740	                break;
741	            case HNS_ROCE_SQ_OP_ATOMIC_WRITE:
742	                lite_wc->opcode = (enum rdma_lite_wc_opcode)HNS_ROCE_WC_ATOMIC_WRITE;
743	                break;
744	            default:
745	                lite_wc->status = RDMA_LITE_WC_GENERAL_ERR;
746	                roce_err("unknown opcode: 0x%08x", opcode);
747	                break;
748	        }
749	    }
750	}
