752	STATIC void hns_roce_lite_poll_one_mark_opcode(int is_send, struct hns_roce_lite_cqe *cqe, struct rdma_lite_wc *lite_wc,
753	    struct rdma_lite_wc_ext *ext)
754	{
755	    if (is_send != 0 || ext == NULL) {
756	        hns_roce_lite_mark_send_opcode(is_send, cqe, lite_wc);
