764	STATIC void dump_err_cqe(const struct hns_roce_lite_cq *cq, const u32 *cqe, u32 wc_status)
765	{
766	#define CQE_ELEMENT_EIGHT 8
767	    int index;
768	
769	    if (wc_status != RDMA_LITE_WC_WR_FLUSH_ERR) {
770	        for (index = 0; index < CQE_ELEMENT_EIGHT; index++) {
771	            roce_err("CQ(0x%lx) CQE(0x%x) INDEX(0x%08x): 0x%08x", cq->cqn, cq->cons_index, index, *(cqe +
772	                index));
773	        }
774	    }
775	}
776	
777	STATIC int hns_roce_lite_poll_one(struct hns_roce_lite_cq *cq, struct hns_roce_lite_qp **cur_qp,
778	    struct rdma_lite_wc *lite_wc, struct rdma_lite_wc_ext *ext)
779	{
780	    struct hns_roce_lite_cqe *cqe = NULL;
781	    int is_send;
782	    u32 qpn;
783	
784	    /* According to CI, find the relative cqe */
785	    cqe = next_cqe_sw(cq);
786	    if (cqe == NULL) {
787	        /* This is normal, don't need record log. */
788	        return CQ_EMPTY;
789	    }
790	
791	    /* Get the next cqe, CI will be added gradually */
792	    ++cq->cons_index;
793	
794	    udma_from_device_barrier();
795	
796	    qpn = roce_get_field(cqe->byte_16, CQE_BYTE_16_LCL_QPN_M, CQE_BYTE_16_LCL_QPN_S);
797	
798	    is_send = (roce_get_bit(cqe->byte_4, CQE_BYTE_4_S_R_S) == HNS_ROCE_LITE_CQE_IS_SQ);
799	
800	    /* if qp is zero, it will not get the correct qpn */
801	    if (*cur_qp == NULL || (qpn & HNS_ROCE_LITE_CQE_QPN_MASK) != (*cur_qp)->lite_qp.qp_num) {
802	        *cur_qp = hns_roce_lite_find_qp(to_hr_lite_ctx(cq->lite_cq.ctx), qpn & 0xffffff);
803	        if (*cur_qp == NULL) {
804	            roce_err("can't find qp!");
805	            return CQ_POLL_ERR;
806	        }
807	    }
808	
809	    hns_roce_lite_poll_one_set_wc(lite_wc, qpn, cur_qp, is_send, cqe);
810	
811	    /*
812	     * HW maintains lite_wc status, set the err type and directly return, after
813	     * generated the incorrect CQE
814	     */
815	    if (roce_get_field(cqe->byte_4, CQE_BYTE_4_STATUS_M, CQE_BYTE_4_STATUS_S) != HNS_ROCE_LITE_CQE_SUCCESS) {
816	        hns_roce_lite_handle_error_cqe(cqe, lite_wc);
817	        dump_err_cqe(cq, (u32 *)cqe, lite_wc->status);
818	        (*cur_qp)->lite_qp.qp_state = RDMA_LITE_QPS_ERR;
819	        return CQ_OK;
820	    }
821	
822	    lite_wc->status = RDMA_LITE_WC_SUCCESS;
823	
824	    /*
825	     * According to the opcode type of cqe, mark the opcode and other
826	     * information of lite_wc
827	     */
828	    hns_roce_lite_poll_one_mark_opcode(is_send, cqe, lite_wc, ext);
829	
830	    return CQ_OK;
831	}
