833	int hns_roce_lite_poll_cq(struct rdma_lite_cq *lite_cq, int num_entries, struct rdma_lite_wc *lite_wc)
834	{
835	    struct hns_roce_lite_cq *cq = NULL;
836	    struct hns_roce_lite_qp *qp = NULL;
837	    int err = CQ_OK;
838	    int npolled;
839	
840	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(lite_cq);
841	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(lite_wc);
842	
843	    cq = to_hr_lite_cq(lite_cq);
844	    if ((cq->flags & HNS_ROCE_LITE_CQ_FLAG_RECORD_DB) == 0) {
845	        roce_err("Lite cq only support record db! cq_flag 0x%x", cq->flags);
846	        return -EINVAL;
847	    }
848	
849	    pthread_spin_lock(&cq->lock);
850	
851	    for (npolled = 0; npolled < num_entries; ++npolled) {
852	        err = hns_roce_lite_poll_one(cq, &qp, lite_wc + npolled, NULL);
853	        if (err != CQ_OK) {
854	            break;
855	        }
856	    }
857	
858	    if (npolled != 0 || err == CQ_POLL_ERR) {
859	        *(u32 *)cq->swdb_buf.hva = cq->cons_index & RECORD_DB_CI_MASK;
860	    }
861	
862	    pthread_spin_unlock(&cq->lock);
863	
864	    return (err == CQ_POLL_ERR) ? err : npolled;
865	}
