867	int hns_roce_lite_poll_cq_v2(struct rdma_lite_cq *lite_cq, int num_entries, struct rdma_lite_wc_v2 *lite_wc)
868	{
869	    struct rdma_lite_wc_v2 *lite_wc_tmp = NULL;
870	    struct rdma_lite_wc_ext *ext = NULL;
871	    struct hns_roce_lite_cq *cq = NULL;
872	    struct hns_roce_lite_qp *qp = NULL;
873	    struct rdma_lite_wc *wc = NULL;
874	    int err = CQ_OK;
875	    int npolled;
876	
877	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(lite_cq);
878	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(lite_wc);
879	
880	    cq = to_hr_lite_cq(lite_cq);
881	    if ((cq->flags & HNS_ROCE_LITE_CQ_FLAG_RECORD_DB) == 0) {
882	        roce_err("Lite cq only support record db! cq_flag 0x%x", cq->flags);
883	        return -EINVAL;
884	    }
885	
886	    pthread_spin_lock(&cq->lock);
887	
888	    for (npolled = 0; npolled < num_entries; ++npolled) {
889	        lite_wc_tmp = lite_wc + npolled;
890	        wc = &lite_wc_tmp->wc;
891	        ext = &lite_wc_tmp->ext;
892	        err = hns_roce_lite_poll_one(cq, &qp, wc, ext);
