896	        ext->version = LITE_WC_EXT_VERSION;
897	    }
898	
899	    if (npolled != 0 || err == CQ_POLL_ERR) {
900	        *(u32 *)cq->swdb_buf.hva = cq->cons_index & RECORD_DB_CI_MASK;
901	    }
902	
903	    pthread_spin_unlock(&cq->lock);
904	
905	    return (err == CQ_POLL_ERR) ? err : npolled;
906	}
