924	STATIC int hns_roce_lite_wq_overflow(struct hns_roce_lite_wq *wq, u32 nreq, struct hns_roce_lite_cq *cq)
925	{
926	    u32 cur;
927	
928	    cur = wq->head - wq->tail;
929	    if (cur + nreq < wq->max_post) {
930	        return 0;
931	    }
932	
933	    pthread_spin_lock(&cq->lock);
934	    cur = wq->head - wq->tail;
935	    pthread_spin_unlock(&cq->lock);
936	
937	    return (cur + nreq) >= wq->max_post;
938	}
