940	STATIC int hns_roce_lite_check_send_wr(struct hns_roce_lite_qp *qp, struct rdma_lite_send_wr *lite_wr, u32 nreq)
941	{
942	    if (hns_roce_lite_wq_overflow(&qp->sq, nreq, to_hr_lite_cq(qp->lite_qp.send_cq))) {
943	        roce_warn("send lite_wq overflow! sq head:%u tail:%u nreq:%u max_post:%d",
944	            qp->sq.head, qp->sq.tail, nreq, qp->sq.max_post);
945	        return -ENOMEM;
