948	    if ((u32)lite_wr->num_sge > qp->sq.max_gs) {
949	        roce_err("send num_sge(%d) in lite_wr is bigger than max_gs(%d)",
950	                 lite_wr->num_sge, qp->sq.max_gs);
951	        return -EINVAL;
952	    }
953	
954	    return 0;
955	}
