967	STATIC __le32 get_immtdata(enum rdma_lite_wr_opcode opcode, const struct rdma_lite_send_wr *lite_wr)
968	{
969	    switch (opcode) {
970	        case RDMA_LITE_WR_SEND_WITH_IMM:
971	        case RDMA_LITE_WR_RDMA_WRITE_WITH_IMM:
972	            return htole32(be32toh(lite_wr->imm_data));
973	        default:
974	            return 0;
