978	STATIC void set_reduce_op(struct hns_roce_lite_rc_sq_wqe *rc_sq_wqe, const struct rdma_lite_post_send_attr *attr)
979	{
980	    roce_set_field(rc_sq_wqe->byte_20, RC_SQ_WQE_BYTE_20_REDUCE_TYPE_M, RC_SQ_WQE_BYTE_20_REDUCE_TYPE_S,
981	        attr->reduce_type & INLINE_REDUCE_TYPE_MASK);
982	    roce_set_field(rc_sq_wqe->byte_20, RC_SQ_WQE_BYTE_20_REDUCE_OP_M, RC_SQ_WQE_BYTE_20_REDUCE_OP_S,
983	        attr->reduce_op & INLINE_REDUCE_OP_MASK);
984	}
985	
986	STATIC int check_rc_opcode(struct hns_roce_lite_rc_sq_wqe *rc_sq_wqe, const struct rdma_lite_send_wr *lite_wr,
987	    struct rdma_lite_post_send_attr *attr)
988	{
989	    u32 opcode = lite_wr->opcode;
990	    int ret = 0;
991	
992	    rc_sq_wqe->immtdata = get_immtdata(opcode, lite_wr);
993	
994	    switch (opcode) {
995	        case RDMA_LITE_WR_REDUCE_WRITE:
996	        case RDMA_LITE_WR_REDUCE_WRITE_NOTIFY:
997	            set_reduce_op(rc_sq_wqe, attr);
998	            rc_sq_wqe->va = htole64(lite_wr->remote_addr);
999	            rc_sq_wqe->rkey = htole32(lite_wr->rkey);
1000	            break;
1001	        case RDMA_LITE_WR_RDMA_READ:
1002	        case RDMA_LITE_WR_RDMA_WRITE:
1003	        case RDMA_LITE_WR_RDMA_WRITE_WITH_IMM:
1004	        case RDMA_LITE_WR_ATOMIC_WRITE:
1005	        case RDMA_LITE_WR_WRITE_WITH_NOTIFY:
1006	            rc_sq_wqe->va = htole64(lite_wr->remote_addr);
1007	            rc_sq_wqe->rkey = htole32(lite_wr->rkey);
1008	            break;
1009	        case RDMA_LITE_WR_SEND:
1010	        case RDMA_LITE_WR_SEND_WITH_IMM:
1011	        case RDMA_LITE_WR_NOP:
1012	            break;
1013	        default:
1014	            ret = -EINVAL;
1015	            break;
1016	    }
1017	
1018	    roce_set_field(rc_sq_wqe->byte_4, RC_SQ_WQE_BYTE_4_OPCODE_M,
1019	                   RC_SQ_WQE_BYTE_4_OPCODE_S, to_hr_lite_opcode(opcode));
1020	    roce_set_bit(rc_sq_wqe->byte_4, RC_SQ_WQE_BYTE_4_CQE_S,
1021	                 (lite_wr->send_flags & RDMA_LITE_SEND_SIGNALED) != 0 ? 1 : 0);
1022	    roce_set_bit(rc_sq_wqe->byte_4, RC_SQ_WQE_BYTE_4_FENCE_S,
1023	                 (lite_wr->send_flags & RDMA_LITE_SEND_FENCE) != 0 ? 1 : 0);
1024	    roce_set_bit(rc_sq_wqe->byte_4, RC_SQ_WQE_BYTE_4_SE_S,
1025	                 (lite_wr->send_flags & RDMA_LITE_SEND_SOLICITED) != 0 ? 1 : 0);
1026	
1027	    return ret;
1028	}
