1030	STATIC void set_data_seg(struct hns_roce_lite_wqe_data_seg *dseg, struct rdma_lite_sge *sg)
1031	{
1032	    dseg->lkey = htole32(sg->lkey);
1033	    dseg->addr = htole64(sg->addr);
1034	    dseg->len = htole32(sg->length);
