1037	STATIC void set_sge(struct hns_roce_lite_wqe_data_seg *dseg, struct hns_roce_lite_qp *qp,
1038	    struct rdma_lite_send_wr *lite_wr, struct hns_roce_lite_sge_info *sge_info)
1039	{
1040	    struct hns_roce_lite_wqe_data_seg *temp_dseg = dseg;
1041	    int i;
1042	
1043	    sge_info->valid_num = 0;
1044	    sge_info->total_len = 0;
1045	
1046	    for (i = 0; i < lite_wr->num_sge; i++) {
1047	        if (likely(lite_wr->sg_list[i].length != 0)) {
1048	            sge_info->total_len += lite_wr->sg_list[i].length;
1049	            sge_info->valid_num++;
1050	
1051	            if ((((lite_wr->send_flags & RDMA_LITE_SEND_INLINE) != 0) &&
1052	                (lite_wr->opcode != RDMA_LITE_WR_ATOMIC_FETCH_AND_ADD) &&
1053	                (lite_wr->opcode != RDMA_LITE_WR_ATOMIC_CMP_AND_SWP)) ||
1054	                (lite_wr->opcode == RDMA_LITE_WR_ATOMIC_WRITE)) {
1055	                continue;
1056	            }
1057	
1058	            /* No inner sge in UD wqe */
1059	            if (sge_info->valid_num <= HNS_ROCE_SGE_IN_WQE && qp->lite_qp.qp_type != RDMA_LITE_QPT_UD) {
1060	                set_data_seg(temp_dseg, lite_wr->sg_list + i);
1061	                temp_dseg++;
1062	            }
1063	        }
1064	    }
1065	}
