1067	STATIC int set_atom_write_seg(struct hns_roce_lite_wqe_data_seg *dseg, struct hns_roce_lite_rc_sq_wqe *rc_sq_wqe,
1068	    struct rdma_lite_send_wr *lite_wr, struct hns_roce_lite_sge_info *sge_info)
1069	{
1070	    // strict maximum support atomic write data to 4B, default capability supports 8B
1071	    if (sge_info->total_len > sizeof(uint32_t)) {
1072	        roce_err("total_len:%u exceeds %zu, disallow to atomic write", sge_info->total_len, sizeof(uint32_t));
1073	        return -EINVAL;
1074	    }
1075	
1076	    roce_set_bit(rc_sq_wqe->byte_4, RC_SQ_WQE_BYTE_4_INLINE_S, 1);
1077	    roce_set_bit(rc_sq_wqe->byte_20, RC_SQ_WQE_BYTE_20_INL_TYPE_S, 0);
1078	
1079	    // atomic write data use 4B in dseg->len field(byte_36)
1080	    dseg->len = htole32(be32toh(lite_wr->imm_data));
1081	    return 0;
1082	}
