1084	STATIC int hns_roce_lite_set_rc_wqe(void *wqe, struct hns_roce_lite_qp *qp,
1085	                                    struct rdma_lite_send_wr *lite_wr, struct rdma_lite_post_send_attr *attr, u32 nreq,
1086	                                    struct hns_roce_lite_sge_info *sge_info)
1087	{
1088	    struct hns_roce_lite_rc_sq_wqe *send_wqe = wqe;
1089	    struct hns_roce_lite_rc_sq_wqe *rc_sq_wqe;
1090	    struct hns_roce_lite_wqe_data_seg *dseg;
1091	    u32 owner_bit;
1092	    u32 wqe_length;
1093	    int ret;
1094	
1095	    // rc wqe固定64字节，最多2个sge
1096	    if (lite_wr->num_sge > RC_MAX_SGE_NUME) {
1097	        roce_err("num_sge[%d] > max sge num[%d].\n", lite_wr->num_sge, RC_MAX_SGE_NUME);
1098	        return -EINVAL;
1099	    }
1100	
1101	    wqe_length = sizeof(struct hns_roce_lite_rc_sq_wqe) +
1102	        sizeof(struct hns_roce_lite_wqe_data_seg) * lite_wr->num_sge;
1103	    rc_sq_wqe = (struct hns_roce_lite_rc_sq_wqe *)calloc(1, wqe_length);
1104	    if (rc_sq_wqe == NULL) {
1105	        roce_err("calloc rc sq wqe failed.\n");
1106	        return -ENOMEM;
1107	    }
1108	
1109	    ret = check_rc_opcode(rc_sq_wqe, lite_wr, attr);
1110	    if (ret) {
1111	        roce_err("unsupported opcode, opcode = %d.\n", lite_wr->opcode);
1112	        goto out;
1113	    }
1114	
1115	    roce_set_field(rc_sq_wqe->byte_20, RC_SQ_WQE_BYTE_20_MSG_START_SGE_IDX_M, RC_SQ_WQE_BYTE_20_MSG_START_SGE_IDX_S,
1116	        sge_info->start_idx & (qp->sge.sge_cnt - 1));
1117	
1118	    dseg = (struct hns_roce_lite_wqe_data_seg *)((char *)rc_sq_wqe + sizeof(struct hns_roce_lite_rc_sq_wqe));
1119	    set_sge(dseg, qp, lite_wr, sge_info);
1120	    rc_sq_wqe->msg_len = htole32(sge_info->total_len);
1121	
1122	    if (lite_wr->opcode == RDMA_LITE_WR_ATOMIC_WRITE) {
1123	        ret = set_atom_write_seg(dseg, rc_sq_wqe, lite_wr, sge_info);
1124	        if (ret != 0) {
1125	            roce_err("set_atom_write_seg failed, ret=%d qpn=%u\n", ret, qp->lite_qp.qp_num);
1126	            goto out;
1127	        }
1128	    }
1129	
1130	    roce_set_field(rc_sq_wqe->byte_16, RC_SQ_WQE_BYTE_16_SGE_NUM_M, RC_SQ_WQE_BYTE_16_SGE_NUM_S, sge_info->valid_num);
1131	    owner_bit = ((qp->sq.head + nreq) >> qp->sq.shift) & 0x1;
1132	    roce_set_bit(rc_sq_wqe->byte_4, RC_SQ_WQE_BYTE_4_OWNER_S, owner_bit);
1133	
1134	    (void)memcpy_s(send_wqe, wqe_length, rc_sq_wqe, wqe_length);
1135	
1136	    if (qp->flags & HNS_ROCE_QP_CAP_OWNER_DB) {
1137	        udma_to_device_barrier();
1138	    }
1139	
1140	    roce_set_bit(send_wqe->byte_4, RC_SQ_WQE_BYTE_4_OWNER_S, ~owner_bit);
1141	out:
1142	    free(rc_sq_wqe);
1143	    rc_sq_wqe = NULL;
1144	    return ret;
1145	}
1146	
1147	STATIC int hns_roce_lite_set_wqe(void *wqe, struct hns_roce_lite_qp *qp,
1148	                                 struct rdma_lite_send_wr *lite_wr, struct rdma_lite_post_send_attr *attr, u32 nreq,
1149	                                 struct hns_roce_lite_sge_info *sge_info)
1150	{
1151	    int ret = 0;
1152	
1153	    switch (qp->lite_qp.qp_type) {
1154	        case RDMA_LITE_QPT_RC:
1155	            ret = hns_roce_lite_set_rc_wqe(wqe, qp, lite_wr, attr, nreq, sge_info);
1156	            break;
1157	        default:
1158	            roce_err("Not supported qp type %d", qp->lite_qp.qp_type);
1159	            return -EINVAL;
1160	    }
1161	
1162	    return ret;
1163	}
1164	
1165	STATIC void hns_roce_lite_get_rsp(struct hns_roce_lite_qp *qp, struct rdma_lite_post_send_resp *resp)
1166	{
1167	    u32 pi = qp->sq.head & ((qp->sq.wqe_cnt << 1) - 1);
1168	
1169	    if (qp->gdr_enabled == HNS_ROCE_QP_AI_MODE_OP ||
1170	        qp->gdr_enabled == HNS_ROCE_QP_AI_MODE_GDR_ASYN ||
1171	        qp->gdr_enabled == HNS_ROCE_QP_AI_MODE_OP_EXT) {
1172	        resp->db.lite_db_info = ((unsigned long)qp->sl << DB_SL_OFFSET) |
1173	                           ((unsigned long)pi << DB_PI_OFFSET) |
1174	                           (0 << DB_QPN_OFFSET) | qp->lite_qp.qp_num;
1175	    }
1176	}
1177	
1178	int hns_roce_lite_post_send(struct rdma_lite_qp *lite_qp, struct rdma_lite_send_wr *lite_wr,
1179	    struct rdma_lite_send_wr **bad_wr, struct rdma_lite_post_send_attr *attr, struct rdma_lite_post_send_resp *resp)
1180	{
1181	    struct rdma_lite_send_wr *lite_wr_temp = NULL;
1182	    struct hns_roce_lite_sge_info sge_info = {0};
1183	    struct hns_roce_lite_qp *qp = NULL;
1184	    void *wqe = NULL;
1185	    u32 wqe_idx = 0;
1186	    u32 nreq = 0;
1187	    int ret;
1188	
1189	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(lite_qp);
1190	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(lite_wr);
1191	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(attr);
1192	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(resp);
1193	
1194	    qp = to_hr_lite_qp(lite_qp);
1195	    lite_wr_temp = lite_wr;
1196	
1197	    ret = check_qp_send_recv(qp);
1198	    if (ret) {
1199	        *bad_wr = lite_wr_temp;
1200	        return ret;
1201	    }
1202	
1203	    pthread_spin_lock(&qp->sq.lock);
1204	    sge_info.start_idx = qp->next_sge; /* start index of extend sge */
1205	
1206	    for (nreq = 0; lite_wr_temp != NULL; ++nreq, lite_wr_temp = lite_wr_temp->next) {
1207	        ret = hns_roce_lite_check_send_wr(qp, lite_wr_temp, nreq);
1208	        if (ret) {
1209	            *bad_wr = lite_wr_temp;
1210	            goto out;
1211	        }
1212	
1213	        wqe_idx = (qp->sq.head + (u32)nreq) & (qp->sq.wqe_cnt - 1);
1214	        wqe = get_send_lite_wqe(qp, wqe_idx);
1215	        qp->sq.wrid[wqe_idx] = lite_wr_temp->wr_id;
1216	
1217	        ret = hns_roce_lite_set_wqe(wqe, qp, lite_wr_temp, attr, nreq, &sge_info);
1218	        if (ret) {
1219	            *bad_wr = lite_wr_temp;
1220	            goto out;
1221	        }
1222	    }
1223	
1224	out:
1225	    qp->sq.head += nreq;
1226	    qp->next_sge = sge_info.start_idx;
1227	
1228	    if (qp->flags & HNS_ROCE_QP_CAP_SQ_RECORD_DB) {
1229	        *(u32 *)qp->sdb_buf.hva = qp->sq.head & 0xffff;
1230	    }
1231	
1232	    pthread_spin_unlock(&qp->sq.lock);
1233	
1234	    hns_roce_lite_get_rsp(qp, resp);
1235	
1236	    return ret;
1237	}
1238	
1239	STATIC void hns_roce_lite_post_recv_out(int nreq, struct hns_roce_lite_qp *qp)
1240	{
1241	    if (nreq == 0) {
1242	        return;
1243	    }
1244	
1245	    qp->rq.head += (u32)nreq;
1246	    udma_to_device_barrier();
1247	    *(u32 *)qp->rdb_buf.hva = qp->rq.head & 0xffff;
1248	}
1249	
1250	STATIC void hns_roce_lite_post_recv_fill_dseg(struct hns_roce_lite_qp *qp, struct rdma_lite_recv_wr *lite_wr,
1251	    struct hns_roce_lite_wqe_data_seg *dseg)
1252	{
1253	    struct hns_roce_lite_wqe_data_seg *temp_dseg = dseg;
1254	    int i;
1255	
1256	    for (i = 0; i < lite_wr->num_sge; i++) {
1257	        if (likely(lite_wr->sg_list[i].length != 0)) {
1258	            set_data_seg(temp_dseg, lite_wr->sg_list + i);
1259	            temp_dseg++;
1260	        }
1261	    }
1262	
1263	    if (i < (int)qp->rq.max_gs) {
1264	        temp_dseg->len = 0;
1265	        temp_dseg->lkey = htole32(HNS_ROCE_LITE_INVALID_SGE_KEY);
1266	        temp_dseg->addr = 0;
1267	    }
1268	}
1269	
1270	STATIC int hns_roce_lite_check_recv_wr(struct hns_roce_lite_qp *qp, struct rdma_lite_recv_wr *lite_wr, u32 nreq)
1271	{
1272	    if (hns_roce_lite_wq_overflow(&qp->rq, nreq, to_hr_lite_cq(qp->lite_qp.recv_cq))) {
1273	        roce_warn("recv lite_wq overflow! rq head:%u tail:%u nreq:%u max_post:%d",
1274	            qp->rq.head, qp->rq.tail, nreq, qp->rq.max_post);
1275	        return -ENOMEM;
1276	    }
1277	
1278	    if ((u32)lite_wr->num_sge > qp->rq.max_gs) {
1279	        roce_err("recv num_sge(%d) in lite_wr is bigger than max_gs(%u)",
1280	                 lite_wr->num_sge, qp->rq.max_gs);
1281	        return -EINVAL;
1282	    }
1283	
1284	    return 0;
1285	}
1286	
1287	int hns_roce_lite_post_recv(struct rdma_lite_qp *lite_qp, struct rdma_lite_recv_wr *lite_wr,
1288	    struct rdma_lite_recv_wr **bad_wr)
1289	{
1290	    struct hns_roce_lite_wqe_data_seg *dseg = NULL;
1291	    struct rdma_lite_recv_wr *lite_wr_temp = NULL;
1292	    struct hns_roce_lite_qp *qp = NULL;
1293	    void *wqe = NULL;
1294	    u32 wqe_idx = 0;
1295	    int nreq = 0;
1296	    int ret = 0;
1297	
1298	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(lite_qp);
1299	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(lite_wr);
1300	    HNS_ROCE_U_NULL_POINT_RETURN_ERR(bad_wr);
1301	
1302	    qp = to_hr_lite_qp(lite_qp);
1303	    lite_wr_temp = lite_wr;
1304	
1305	    ret = check_qp_send_recv(qp);
1306	    if (ret) {
1307	        *bad_wr = lite_wr_temp;
1308	        return ret;
1309	    }
1310	
1311	    pthread_spin_lock(&qp->rq.lock);
1312	
1313	    for (nreq = 0; lite_wr_temp != NULL; ++nreq, lite_wr_temp = lite_wr_temp->next) {
1314	        ret = hns_roce_lite_check_recv_wr(qp, lite_wr_temp, (u32)nreq);
1315	        if (ret) {
1316	            *bad_wr = lite_wr_temp;
1317	            goto out;
1318	        }
1319	
1320	        wqe_idx = (qp->rq.head + (u32)nreq) & (qp->rq.wqe_cnt - 1);
1321	        wqe = get_recv_lite_wqe(qp, wqe_idx);
1322	        qp->rq.wrid[wqe_idx] = lite_wr_temp->wr_id;
1323	
1324	        dseg = (struct hns_roce_lite_wqe_data_seg *)wqe;
1325	
1326	        hns_roce_lite_post_recv_fill_dseg(qp, lite_wr_temp, dseg);
1327	    }
1328	
1329	out:
1330	    hns_roce_lite_post_recv_out(nreq, qp);
1331	
1332	    pthread_spin_unlock(&qp->rq.lock);
1333	
1334	    return ret;
1335	}
