114	int hns_roce_store_lite_qp(struct hns_roce_lite_context *ctx, uint32_t qpn, struct hns_roce_lite_qp *qp)
115	{
116	    uint32_t tind = (qpn & ((uint32_t)ctx->num_qps - 1)) >> (uint32_t)ctx->qp_table_shift;
117	
118	    if (ctx->qp_table[tind].refcnt == 0) {
119	        HNS_ROCE_U_PARA_CHECK_RETURN_INT((ctx->qp_table_mask + 1));
120	        ctx->qp_table[tind].table = calloc((unsigned long)(ctx->qp_table_mask + 1), sizeof(struct hns_roce_lite_qp *));
121	        if (ctx->qp_table[tind].table == NULL) {
122	            roce_err("calloc qp table failed, qp_table_mask is 0x%x", ctx->qp_table_mask);
123	            return -1;
124	        }
125	    }
126	
127	    ctx->qp_table[tind].refcnt++;
128	    ctx->qp_table[tind].table[qpn & (u32)(ctx->qp_table_mask)] = qp;
129	
130	    return 0;
131	}
132	
133	void hns_roce_clear_lite_qp(struct hns_roce_lite_context *ctx, uint32_t qpn)
134	{
135	    u32 tind = (qpn & ((u32)(ctx->num_qps) - 1)) >> (u32)ctx->qp_table_shift;
136	
137	    if (--ctx->qp_table[tind].refcnt == 0) {
138	        free(ctx->qp_table[tind].table);
139	        ctx->qp_table[tind].table = NULL;
140	    } else {
141	        ctx->qp_table[tind].table[qpn & (uint32_t)(ctx->qp_table_mask)] = NULL;
142	    }
143	}
144	
145	void *hns_roce_lite_mmap_host_va(u64 device_va, u32 device_va_len, struct hns_roce_lite_context *ctx)
146	{
147	    u64 align_va = align_down(device_va, ctx->page_size);
148	    u64 align_len = align_up(device_va_len, ctx->page_size);
149	    void *dst_addr;
150	    int ret;
151	
152	    ret = halHostRegister((void *)align_va, align_len, DEV_MEM_MAP_HOST | MEM_REGISTER_HCCP_PROC_TYPE, ctx->dev_id,
153	        &dst_addr);
154	    if (ret) {
155	        roce_err("hns_roce_lite_mmap_host_va halHostRegister failed, "
156	            "device va: 0x%llx, len: 0x%x, align device len: 0x%llx", device_va, device_va_len, align_len);
157	        return NULL;
158	    }
159	
160	    dst_addr = (align_va ^ device_va) + (char *)dst_addr;
161	
162	    return dst_addr;
163	}
164	
165	int hns_roce_lite_unmmap_host_va(u64 device_va, struct hns_roce_lite_context *ctx)
166	{
167	    u64 align_va = align_down(device_va, ctx->page_size);
168	    int ret;
169	
170	    if (ctx->lite_ctx.restore_flag != 0) {
171	        return 0;
172	    }
173	
174	    ret = halHostUnregisterEx((void *)align_va, ctx->dev_id, DEV_MEM_MAP_HOST | MEM_REGISTER_HCCP_PROC_TYPE);
175	    if (ret) {
176	        roce_err("hns_roce_lite_unmmap_host_va halHostUnregisterEx failed, device va: 0x%llx, ret = %d", align_va, ret);
177	        return ret;
178	    }
179	
180	    return 0;
181	}
182	
183	STATIC void *hns_roce_lite_mmap_db(u64 device_va, u32 dva_len, struct hns_roce_lite_context *ctx)
184	{
185	    u64 align_va = align_down(device_va, ctx->page_size);
186	    struct db_dva_node *db_node = NULL;
187	    struct db_dva_node *db_next = NULL;
188	    void *host_va = NULL;
189	
190	    (void)pthread_mutex_lock(&ctx->mutex);
191	    list_for_each(&ctx->db_list, db_next, entry) {
192	        if (db_next->db_align_dva == align_va) {
193	            host_va = (void *)align_down((u64)db_next->hva, ctx->page_size);
194	            host_va = (align_va ^ device_va) + (char *)host_va;
195	            db_next->ref_cnt++;
196	            goto out;
197	        }
198	    }
199	
200	    db_node = (struct db_dva_node *)calloc(1, sizeof(struct db_dva_node));
201	    if (db_node == NULL) {
202	        roce_err("%s calloc db_node failed", __func__);
203	        (void)pthread_mutex_unlock(&ctx->mutex);
204	        return NULL;
205	    }
206	
207	    host_va = hns_roce_lite_mmap_host_va(device_va, dva_len, ctx);
208	    if (host_va == NULL) {
209	        free(db_node);
210	        roce_err("%s hns_roce_lite_mmap_host_va host_va failed", __func__);
211	        goto out;
212	    }
213	
214	    db_node->db_align_dva = align_va;
215	    db_node->hva = host_va;
216	    db_node->ref_cnt++;
217	    list_add_tail(&ctx->db_list, &db_node->entry);
218	
219	out:
220	    (void)pthread_mutex_unlock(&ctx->mutex);
221	
222	    return host_va;
223	}
224	
225	STATIC int hns_roce_lite_unmmap_db(u64 device_va, struct hns_roce_lite_context *ctx)
226	{
227	    u64 align_va = align_down(device_va, ctx->page_size);
228	    struct db_dva_node *db_next = NULL;
229	    int ret;
230	
231	    (void)pthread_mutex_lock(&ctx->mutex);
232	    list_for_each(&ctx->db_list, db_next, entry) {
233	        if (db_next->db_align_dva == align_va) {
234	            db_next->ref_cnt--;
235	            if (db_next->ref_cnt == 0) {
236	                list_del(&db_next->entry);
237	                free(db_next);
238	                db_next = NULL;
239	                ret = hns_roce_lite_unmmap_host_va(device_va, ctx);
240	                if (ret) {
241	                    roce_err("hns_roce_lite_unmmap_host_va failed, ret = %d", ret);
242	                    (void)pthread_mutex_unlock(&ctx->mutex);
243	                    return ret;
244	                }
245	            }
246	            goto out;
247	        }
248	    }
249	
250	out:
251	    (void)pthread_mutex_unlock(&ctx->mutex);
252	    return 0;
253	}
254	
255	int hns_roce_lite_mmap_hva(struct rdma_lite_device_buf *dev_buf, struct rdma_lite_host_buf *host_buf,
256	    struct hns_roce_lite_context *ctx)
257	{
258	    struct rdma_lite_mem_pool *mem_pool = NULL;
259	    unsigned int alloc_size = 0;
260	
261	    host_buf->dva = dev_buf->va;
262	    host_buf->length = dev_buf->len;
263	    if (ctx->page_size == PAGE_ALIGN_4KB) {
264	        host_buf->hva = hns_roce_lite_mmap_host_va(dev_buf->va, host_buf->length, ctx);
265	        goto page_align_4k_out;
266	    }
267	
268	    if (host_buf->mem_idx >= BITMAP_WORD_SIZE) {
269	        roce_err("param error, mem_idx[%u] >= %u", host_buf->mem_idx, BITMAP_WORD_SIZE);
270	        return -EINVAL;
271	    }
272	
273	    mem_pool = ctx->mem_pool_list[host_buf->mem_idx];
274	    if (mem_pool == NULL) {
275	        roce_err("param error, mem_idx[%u] not found in mem_pool_list", host_buf->mem_idx);
276	        return -EIO;
277	    }
278	
279	    alloc_size = (unsigned int)align_up(host_buf->length, PAGE_ALIGN_4KB);
280	    if (mem_pool->offset + alloc_size > mem_pool->host_buf.length) {
281	        roce_err("mem pool mem exhaust, mem_idx:%u, alloc_size:0x%x", host_buf->mem_idx, alloc_size);
282	        return -ENOMEM;
283	    }
